using NJsonSchema;
using NSwag;

namespace Recommand.Generator.Normalizers;

/// <summary>
/// A response that can be either text or a binary file (render: HTML or PDF)
/// is generated by NSwag from its first content type, i.e. as a string,
/// which corrupts the binary case. Dropping the text alternative makes the
/// method return a stream (<c>FileResponse</c>), which carries both.
/// </summary>
internal sealed class MixedContentResponseNormalizer : ISpecNormalizer
{
    public void Normalize(OpenApiDocument document)
    {
        foreach (var operation in document.Paths.Values.SelectMany(p => p.ActualPathItem.Values))
        {
            foreach (var response in operation.Responses.Values)
            {
                var binary = response.Content.Where(c => c.Value.Schema?.Format == "binary").Select(c => c.Key).ToList();
                if (binary.Count == 0 || binary.Count == response.Content.Count) continue;

                foreach (var contentType in response.Content.Keys.Except(binary).ToList()) response.Content.Remove(contentType);
                Console.WriteLine($"Mixed-content response @ {operation.OperationId}: kept {string.Join(", ", binary)} so it is returned as a stream.");
            }
        }
    }
}
